type jsonTheme struct {
	colors      map[fyne.ThemeColorName]color.Color
	colorsDark  map[fyne.ThemeColorName]color.Color
	colorsLight map[fyne.ThemeColorName]color.Color
	sizes       map[fyne.ThemeSizeName]float32
	fonts       map[string]fyne.Resource
	icons       map[fyne.ThemeIconName]fyne.Resource
	base        fyne.Theme
}

type jsonThemeData struct {
	Colors      map[string]string `json:"Colors"`
	ColorsDark  map[string]string `json:"Colors-dark"`
	ColorsLight map[string]string `json:"Colors-light"`
	Sizes       map[string]float32 `json:"Sizes"`
	Fonts       map[string]string `json:"Fonts"`
	Icons       map[string]string `json:"Icons"`
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	if variant == fyne.VariantDark {
		if c, ok := t.colorsDark[name]; ok {
			return c
		}
	} else if variant == fyne.VariantLight {
		if c, ok := t.colorsLight[name]; ok {
			return c
		}
	}

	// Check generic colors
	if c, ok := t.colors[name]; ok {
		return c
	}

	// Fall back to base theme
	return t.base.Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	var key string
	if style.Bold && style.Italic {
		key = "boldItalic"
	} else if style.Bold {
		key = "bold"
	} else if style.Italic {
		key = "italic"
	} else if style.Monospace {
		key = "monospace"
	} else {
		key = "regular"
	}

	if f, ok := t.fonts[key]; ok {
		return f
	}

	return t.base.Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if i, ok := t.icons[name]; ok {
		return i
	}

	return t.base.Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if s, ok := t.sizes[name]; ok {
		return s
	}

	return t.base.Size(name)
}

// parseHexColor parses a hex color string with optional # prefix.
// Supports 3, 4, 6, and 8 digit hex formats.
func parseHexColor(hexStr string) (color.Color, error) {
	hexStr = strings.TrimSpace(hexStr)
	hexStr = strings.TrimPrefix(hexStr, "#")

	if len(hexStr) == 0 {
		return color.Transparent, fmt.Errorf("empty hex color string")
	}

	var r, g, b, a uint8
	a = 0xff // default alpha

	switch len(hexStr) {
	case 3:
		// RGB format: "abc" -> 0xaa 0xbb 0xcc 0xff
		val, err := strconv.ParseUint(hexStr, 16, 16)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hexStr)
		}
		r = uint8((val >> 8) & 0xf)
		r = r<<4 | r
		g = uint8((val >> 4) & 0xf)
		g = g<<4 | g
		b = uint8(val & 0xf)
		b = b<<4 | b

	case 4:
		// RGBA format: "abcd" -> 0xaa 0xbb 0xcc 0xdd
		val, err := strconv.ParseUint(hexStr, 16, 16)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hexStr)
		}
		r = uint8((val >> 12) & 0xf)
		r = r<<4 | r
		g = uint8((val >> 8) & 0xf)
		g = g<<4 | g
		b = uint8((val >> 4) & 0xf)
		b = b<<4 | b
		a = uint8(val & 0xf)
		a = a<<4 | a

	case 6:
		// RRGGBB format
		val, err := strconv.ParseUint(hexStr, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hexStr)
		}
		r = uint8((val >> 16) & 0xff)
		g = uint8((val >> 8) & 0xff)
		b = uint8(val & 0xff)

	case 8:
		// RRGGBBAA format
		val, err := strconv.ParseUint(hexStr, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hexStr)
		}
		r = uint8((val >> 24) & 0xff)
		g = uint8((val >> 16) & 0xff)
		b = uint8((val >> 8) & 0xff)
		a = uint8(val & 0xff)

	default:
		return color.Transparent, fmt.Errorf("invalid hex color length: %s", hexStr)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// FromJSON parses a JSON string and returns a Theme.
