package binding

import (
	"fmt"

	"fyne.io/fyne/v2/storage"
)

type sprintfBinding struct {
	base

	format  string
	sources []DataItem
	str     string
	err     error
}

// NewSprintf creates a formatted string binding that combines multiple data sources.
// When any source binding changes, the formatted string is automatically updated using fmt.Sprintf.
// The Set() method parses the string back using fmt.Sscanf and updates each source binding.
func NewSprintf(format string, sources ...DataItem) String {
	if len(sources) == 0 {
		return NewString()
	}

	b := &sprintfBinding{
		format:  format,
		sources: sources,
	}

	// Listen to all source bindings
	for _, src := range sources {
		src.AddListener(b)
	}

	// Initial update
	b.updateString()

	return b
}

func (b *sprintfBinding) Get() (string, error) {
	b.lock.RLock()
	defer b.lock.RUnlock()

	return b.str, b.err
}

func (b *sprintfBinding) Set(str string) error {
	b.lock.Lock()
	defer b.lock.Unlock()

	// Parse the string back into source values
	values := make([]interface{}, len(b.sources))
	for i, src := range b.sources {
		switch src.(type) {
		case Bool:
			var v bool
			values[i] = &v
		case Bytes:
			// Bytes cannot be round-tripped via Sscanf
			return fmt.Errorf("cannot parse Bytes binding from string")
		case Float:
			var v float64
			values[i] = &v
		case Int:
			var v int
			values[i] = &v
		case Rune:
			var v rune
			values[i] = &v
		case String:
			var v string
			values[i] = &v
		case URI:
			var v string
			values[i] = &v
		default:
			return fmt.Errorf("unsupported binding type")
		}
	}

	_, err := fmt.Sscanf(str, b.format, values...)
	if err != nil {
		return err
	}

	// Set each source to the parsed value
	for i, src := range b.sources {
		switch s := src.(type) {
		case Bool:
			if err := s.Set(*values[i].(*bool)); err != nil {
				return err
			}
		case Float:
			if err := s.Set(*values[i].(*float64)); err != nil {
				return err
			}
		case Int:
			if err := s.Set(*values[i].(*int)); err != nil {
				return err
			}
		case Rune:
			if err := s.Set(*values[i].(*rune)); err != nil {
				return err
			}
		case String:
			if err := s.Set(*values[i].(*string)); err != nil {
				return err
			}
		case URI:
			uri, err := storage.ParseURI(*values[i].(*string))
			if err != nil {
				return err
			}
			if err := s.Set(uri); err != nil {
				return err
			}
		}
	}

	b.str = str
	b.err = nil
	b.trigger()

	return nil
}

func (b *sprintfBinding) DataChanged() {
	b.updateString()
}

func (b *sprintfBinding) updateString() {
	b.lock.Lock()
	defer b.lock.Unlock()

	// Read all source values
	values := make([]interface{}, len(b.sources))
	for i, src := range b.sources {
		var val interface{}
		var err error

		switch s := src.(type) {
		case Bool:
			val, err = s.Get()
		case Bytes:
			val, err = s.Get()
		case Float:
			val, err = s.Get()
		case Int:
			val, err = s.Get()
		case Rune:
			val, err = s.Get()
		case String:
			val, err = s.Get()
		case URI:
			val, err = s.Get()
		default:
			b.err = fmt.Errorf("unsupported binding type at index %d", i)
			b.trigger()
			return
		}

		if err != nil {
			b.err = err
			b.trigger()
			return
		}

		values[i] = val
	}

	// Format the string
	b.str = fmt.Sprintf(b.format, values...)
	b.err = nil
	b.trigger()
}

// StringToStringWithFormat wraps a String binding with a format string.
// If the format is "%s" (identity), returns the original binding directly.
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

