package validation

import "fyne.io/fyne/v2"

// NewAllOf returns a validator that requires all child validators to pass.
// If any validator fails, the first error encountered is returned.
func NewAllOf(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		for _, v := range validators {
			if v == nil {
				continue
			}
			if err := v(text); err != nil {
				return err
			}
		}
		return nil
	}
}

