// App defines desktop-specific application features beyond the standard fyne.App interface.
// This is typically used to provide platform-specific UI features such as system tray integration.
//
// Since: 2.2
type App interface {
	fyne.App

	// SetSystemTrayMenu sets the menu for the application's system tray icon.
	// The icon will be displayed in the system tray/status bar area.
	// Passing nil will hide the system tray icon.
	SetSystemTrayMenu(menu *fyne.Menu)

	// SetSystemTrayIcon sets a custom icon for the system tray.
	// If not set, the application icon will be used.
	SetSystemTrayIcon(icon fyne.Resource)
}

